<script setup lang="ts">
const busyAction=ref<'login'|'logout'>('login')
import {platformLanding} from '../../utils/console-navigation'
import SiteLegalFooter from "./SiteLegalFooter.vue"
import AuthLoginShell from '@orangezh1/qisvc-console-ui/components/AuthLoginShell'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
const props=defineProps<{portal:'admin'|'tenant'}>()
const auth=useApi(props.portal),username=ref<string|number>(''),password=ref<string|number>(''),showPassword=ref(false),busy=ref(false),ready=ref(false),error=ref('')
const platform=computed(()=>props.portal==='admin')
const matched=computed(()=>auth.session.value?.role===(platform.value?'root':'tenant'))
const entryName=computed(()=>platform.value?'总后台':'后台')
const {site}=useSiteBranding()
const brand=computed(()=>platform.value?site.value!.platform:site.value!.tenant)
const loginTitle=computed(()=>brand.value.loginTitle)
const loginDescription=computed(()=>brand.value.loginDescription)
const logo=computed(()=>brand.value.logo||'/brand/qicore.png')
const points=computed(()=>platform.value?['管理租户开通与授权','统一后台身份与平台权限','维护服务配置与操作审计']:['管理成员和权限','维护业务配置','查看运营数据'])
onMounted(()=>{ready.value=true})
async function submit(){if(!ready.value||busy.value)return;if(!username.value||!password.value){error.value='请输入账号和密码';return}busyAction.value='login';busy.value=true;try{await auth.login(String(username.value),String(password.value),props.portal);password.value='';error.value='';await navigateTo(props.portal==='admin'?platformLanding(auth.session.value!) :'/admin',{replace:true,external:true})}catch(e){error.value=e instanceof Error?e.message:'登录未完成'}finally{busy.value=false}}
async function logout(){if(!ready.value||busy.value)return;busyAction.value='logout';busy.value=true;try{await auth.logout()}catch(e){error.value=e instanceof Error?e.message:'退出未完成'}finally{busy.value=false}}
// Both explicit tenant and dynamic platform routes reuse the SSR result,
// including a signed-out result, instead of checking again during hydration.
const {data:restored}=await useAsyncData('login-session-'+props.portal,async()=>({session:await auth.restore()}))
const restoredSession=restored.value?.session
if(restoredSession?.role===(platform.value?'root':'tenant'))await navigateTo(platform.value?platformLanding(restoredSession) :'/admin',{replace:true,external:true})
</script>
<template><div class="admin-login-layout"><aside class="admin-login-aside"><NuxtLink :to="`/admin/login`" class="admin-login-brand"><img class="admin-brand-logo" :src="logo" :alt="brand.name+' Logo'"/><div><b>{{brand.name}}</b><small>MANAGEMENT CONSOLE</small></div></NuxtLink><div class="admin-login-intro"><div class="admin-login-eyebrow">{{platform?'平台管理入口':'后台入口'}}</div><h1>{{loginTitle}}</h1><p>{{loginDescription}}</p><img v-if="brand.loginImage" :src="brand.loginImage" class="admin-login-illustration" alt="登录页配图"/><ul v-if="!brand.loginImage"><li v-for="point in points" :key="point"><UIcon name="i-lucide-circle-check"/>{{point}}</li></ul></div><footer>{{brand.name}} <span>·</span> {{entryName}}</footer></aside><AuthLoginShell class="admin-login-form" :title="entryName+'登录'" description="使用已获得授权的后台账号登录" icon="i-lucide-shield-check"><template #brand><div class="admin-login-mobile-brand"><img :src="logo" alt=""/>{{brand.name}}</div></template><form method="post" class="space-y-5" @submit.prevent="submit"><UAlert v-if="auth.session.value&&!matched" color="warning" title="当前会话属于另一后台入口" description="请先退出，再使用当前后台的授权账号登录。"/><UFormField label="账号" name="username" required><ConsoleInput v-model="username" autocomplete="username" placeholder="请输入后台账号" icon="i-lucide-user-round" :disabled="!ready" :readonly="busy" /></UFormField><UFormField label="密码" name="password" required><ConsoleInput v-model="password" :type="showPassword?'text':'password'" autocomplete="current-password" placeholder="请输入密码" icon="i-lucide-lock-keyhole" :maxlength="128" :disabled="!ready" :readonly="busy"><template #trailing><UButton type="button" color="neutral" variant="link" :icon="showPassword?'i-lucide-eye-off':'i-lucide-eye'" :aria-label="showPassword?'隐藏密码':'显示密码'" :disabled="busy||!ready" @click="showPassword=!showPassword"/></template></ConsoleInput></UFormField><div class="admin-login-feedback" aria-live="polite"><UAlert v-if="error" color="error" :title="error"/></div><ConsoleFormActions><UButton type="submit" block :disabled="busy||!ready" :loading="busy&&busyAction==='login'">登录{{entryName}}</UButton></ConsoleFormActions><UButton v-if="auth.session.value&&!matched" block color="neutral" variant="ghost" :disabled="busy||!ready" :loading="busy&&busyAction==='logout'" @click="logout">退出当前会话</UButton></form><template #footer><SiteLegalFooter/></template></AuthLoginShell></div></template>
<style scoped>
.admin-login-feedback{min-height:72px;display:grid;align-content:start}
.admin-login-layout{min-height:100svh;display:grid;grid-template-columns:minmax(360px,44%) minmax(0,1fr);font-family:"PingFang SC","Microsoft YaHei",system-ui,sans-serif;background:var(--ui-bg)}.admin-login-aside{display:flex;flex-direction:column;padding:48px 54px;background:linear-gradient(145deg,#102d52,#145197);color:white;min-height:100svh}.admin-login-brand{display:flex;align-items:center;gap:13px;width:max-content;color:white;text-decoration:none}.admin-brand-logo{width:48px;height:48px;object-fit:contain}.admin-login-brand b{font-size:23px;font-weight:650;display:block;line-height:1.3;letter-spacing:2px}.admin-login-brand small{font-size:8px;letter-spacing:2.1px;color:#bdd3eb;display:block;margin-top:5px}.admin-login-intro{margin:auto 0;padding:65px 0}.admin-login-eyebrow{font-size:12px;letter-spacing:2.5px;color:#90b9e3;margin-bottom:24px}.admin-login-illustration{display:block;width:100%;max-height:300px;object-fit:contain;margin-top:24px}.admin-login-intro h1{white-space:pre-line;font-size:36px;font-weight:650;line-height:1.5;letter-spacing:.7px;margin:0}.admin-login-intro>p{max-width:340px;font-size:14px;line-height:1.9;color:#afc9e5;margin:22px 0 28px}.admin-login-intro ul{padding:0;list-style:none;display:flex;flex-direction:column;gap:15px;font-size:13px;color:#d4e4f7}.admin-login-intro li{display:flex;align-items:center;gap:11px}.admin-login-intro li>.iconify{color:#a4c7ed;font-size:18px}.admin-login-aside>footer{font-size:11px;color:#8caed5;letter-spacing:.3px}.admin-login-aside>footer>span{margin:0 9px}.admin-login-form{min-height:100svh;padding:38px!important;background:var(--ui-bg)!important;position:relative}.admin-login-form :deep(>.surface-card){max-width:28rem;width:100%;border:0;box-shadow:none;background:transparent}.admin-login-form :deep(>.surface-card>[data-slot=body]){padding:16px}.admin-login-form :deep(h1){font-size:26px}.admin-login-mobile-brand{display:none}.admin-login-form :deep([data-slot=input]){height:42px}.admin-login-environment{font-size:10px;line-height:1.7;color:var(--ui-text-dimmed);margin-top:16px}.admin-login-form :deep(form .qisvc-console-form-actions){margin-top:28px}@media(max-width:1023px){.admin-login-layout{grid-template-columns:minmax(300px,42%) 1fr}.admin-login-aside{padding:35px 30px}.admin-login-intro h1{font-size:29px}.admin-login-form{padding:25px!important}}@media(max-width:760px){.admin-login-layout{display:block}.admin-login-aside{display:none}.admin-login-form{min-height:100svh;padding:25px 18px!important}.admin-login-mobile-brand{display:flex;align-items:center;justify-content:center;gap:9px;color:var(--ui-primary);font-size:14px;font-weight:650}.admin-login-mobile-brand>img{width:28px;height:28px;object-fit:contain}.admin-login-form :deep(>.surface-card>[data-slot=body]){padding:14px 4px}}
</style>
